public class Query
{
    private readonly IBookRepository _repository;

    public Query(IBookRepository repository)
    {
        _repository = repository;
    }

    [Query]
    public IEnumerable<Book> GetBooks() => _repository.GetAll();

    [Query(Name = "book")]
    public Book? GetBookById(int id) => _repository.GetById(id);
}

[Query]
public IEnumerable<Book> GetBooksByGenre(Genre genre)
{
    return _repository.GetAll().Where(b => b.Genre == genre);
}

// Client query:
